('30000000-0000-0000-0000-000000001922', 'sustainable', '/səˈsteɪnəbəl/', 'adjective', 'sustentável', 'They switched to sustainable packaging last year.', 'Eles passaram a usar embalagens sustentáveis no ano passado.', 'B2', array['environment']),
