('30000000-0000-0000-0000-000000001927', 'climate crisis', '/ˈklaɪmət ˈkraɪsɪs/', 'noun', 'crise climática', 'Scientists warn that the climate crisis is accelerating.', 'Cientistas alertam que a crise climática está se acelerando.', 'B2', array['environment']),
