('30000000-0000-0000-0000-000000001929', 'deforestation', '/diːˌfɒrɪˈsteɪʃən/', 'noun', 'desmatamento', 'Deforestation has increased in the region this year.', 'O desmatamento aumentou na região este ano.', 'B2', array['environment']),
('30000000-0000-0000-0000-000000001930', 'ecosystem', '/ˈiːkoʊsɪstəm/', 'noun', 'ecossistema', 'The oil spill damaged the local ecosystem.', 'O vazamento de óleo danificou o ecossistema local.', 'B2', array['environment']),
('30000000-0000-0000-0000-000000001931', 'conservation', '/ˌkɑːnsərˈveɪʃən/', 'noun', 'conservação', 'The organization focuses on wildlife conservation.', 'A organização se concentra na conservação da vida selvagem.', 'B2', array['environment']),
