('30000000-0000-0000-0000-000000001933', 'contaminate', '/kənˈtæmɪneɪt/', 'verb', 'contaminar', 'The chemical spill contaminated the river.', 'O vazamento químico contaminou o rio.', 'B2', array['environment']),
('30000000-0000-0000-0000-000000001934', 'endangered', '/ɪnˈdeɪndʒərd/', 'adjective', 'ameaçado de extinção', 'This species has been endangered for decades.', 'Esta espécie está ameaçada de extinção há décadas.', 'B2', array['environment']),
