('30000000-0000-0000-0000-000000001937', 'drought', '/draʊt/', 'noun', 'seca', 'The region has suffered a severe drought this year.', 'A região sofreu uma seca severa este ano.', 'B2', array['environment']),
('30000000-0000-0000-0000-000000001938', 'wildfire', '/ˈwaɪldfaɪər/', 'noun', 'incêndio florestal', 'The wildfire destroyed thousands of acres of forest.', 'O incêndio florestal destruiu milhares de acres de floresta.', 'B2', array['environment']),
('30000000-0000-0000-0000-000000001939', 'rising sea levels', '/ˈraɪzɪŋ siː ˈlevəlz/', 'phrase', 'elevação do nível do mar', 'Rising sea levels threaten coastal cities.', 'A elevação do nível do mar ameaça cidades costeiras.', 'B2', array['environment']),
('30000000-0000-0000-0000-000000001940', 'recycle', '/riːˈsaɪkəl/', 'verb', 'reciclar', 'We should recycle plastic bottles and paper.', 'Devemos reciclar garrafas plásticas e papel.', 'B2', array['environment']),
('30000000-0000-0000-0000-000000001941', 'waste', '/weɪst/', 'noun', 'resíduo/desperdício', 'The factory produces too much waste.', 'A fábrica produz muito resíduo.', 'B2', array['environment']),
('30000000-0000-0000-0000-000000001942', 'eco-friendly', '/ˈiːkoʊ ˈfrendli/', 'adjective', 'ecológico', 'More companies are choosing eco-friendly materials.', 'Mais empresas estão escolhendo materiais ecológicos.', 'B2', array['environment']),
('30000000-0000-0000-0000-000000001943', 'offset', '/ˈɔːfset/', 'verb', 'compensar', 'The airline offers to offset your flight''s emissions.', 'A companhia aérea oferece compensar as emissões do seu voo.', 'B2', array['environment']),
('30000000-0000-0000-0000-000000001944', 'mitigate', '/ˈmɪtɪɡeɪt/', 'verb', 'mitigar', 'New policies aim to mitigate the effects of climate change.', 'Novas políticas visam mitigar os efeitos da mudança climática.', 'B2', array['environment']),
('30000000-0000-0000-0000-000000001945', 'resilience', '/rɪˈzɪliəns/', 'noun', 'resiliência', 'The city is building resilience against future floods.', 'A cidade está construindo resiliência contra futuras enchentes.', 'B2', array['environment']),
('30000000-0000-0000-0000-000000001946', 'natural resources', '/ˈnætʃərəl rɪˈsɔːrsɪz/', 'phrase', 'recursos naturais', 'We must manage natural resources more wisely.', 'Precisamos gerenciar os recursos naturais de forma mais sensata.', 'B2', array['environment']),
('30000000-0000-0000-0000-000000001947', 'overconsumption', '/ˌoʊvərkənˈsʌmpʃən/', 'noun', 'consumo excessivo', 'Overconsumption is putting pressure on the planet.', 'O consumo excessivo está pressionando o planeta.', 'B2', array['environment']),
('30000000-0000-0000-0000-000000001948', 'global warming', '/ˈɡloʊbəl ˈwɔːrmɪŋ/', 'noun', 'aquecimento global', 'Global warming is causing more extreme weather events.', 'O aquecimento global está causando mais eventos climáticos extremos.', 'B2', array['environment']),
('30000000-0000-0000-0000-000000001949', 'environmental impact', '/ɪnˌvaɪrənˈmentəl ˈɪmpækt/', 'phrase', 'impacto ambiental', 'The project''s environmental impact was carefully assessed.', 'O impacto ambiental do projeto foi cuidadosamente avaliado.', 'B2', array['environment']),
