('20000000-0000-0000-0000-000000000321', 'word_order', 9, '{"words": ["Flying", "often", "increases", "your", "carbon", "footprint", "significantly"], "correct_sentence": "Flying often increases your carbon footprint significantly", "translation": "Voar com frequência aumenta significativamente sua pegada de carbono"}'),
('20000000-0000-0000-0000-000000000321', 'word_order', 10, '{"words": ["The", "new", "law", "aims", "to", "reduce", "carbon", "emissions"], "correct_sentence": "The new law aims to reduce carbon emissions", "translation": "A nova lei visa reduzir as emissões de carbono"}'),
('20000000-0000-0000-0000-000000000321', 'reading', 11, '{"passage": "Sustainability has become central to how companies operate. Many now measure their carbon footprint, invest in renewable energy, and try to protect biodiversity in the regions where they work. These efforts aim to keep business practices sustainable while reducing harmful emissions.", "translation": "Sustentabilidade se tornou central para como as empresas operam. Muitas agora medem sua pegada de carbono, investem em energia renovável e tentam proteger a biodiversidade nas regiões onde atuam. Esses esforços visam manter práticas de negócio sustentáveis enquanto reduzem emissões nocivas.", "question": "What do many companies now measure, according to the text?", "options": ["Their profits only", "Their carbon footprint", "Their biodiversity budget"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000321', 'listening', 12, '{"audio_text": "Sustainability is now a priority for most companies. The country invested heavily in renewable energy. The rainforest is home to incredible biodiversity.", "question": "What did the country invest heavily in, according to the audio?", "options": ["Fossil fuels", "Renewable energy", "Tourism"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000321', 'dictation', 13, '{"audio_text": "Sustainability is now a priority for most companies.", "expected": "Sustainability is now a priority for most companies."}'),
('20000000-0000-0000-0000-000000000321', 'typing', 14, '{"prompt_pt": "Traduza: ''Investir em energia renovável reduz a pegada de carbono da empresa.''", "expected": "Investing in renewable energy reduces the company''s carbon footprint.", "ai_review": true}'),

