('20000000-0000-0000-0000-000000000322', 'word_order', 9, '{"words": ["Deforestation", "has", "increased", "in", "the", "region", "this", "year"], "correct_sentence": "Deforestation has increased in the region this year", "translation": "O desmatamento aumentou na região este ano"}'),
('20000000-0000-0000-0000-000000000322', 'word_order', 10, '{"words": ["The", "organization", "focuses", "on", "wildlife", "conservation"], "correct_sentence": "The organization focuses on wildlife conservation", "translation": "A organização se concentra na conservação da vida selvagem"}'),
('20000000-0000-0000-0000-000000000322', 'reading', 11, '{"passage": "Experts describe the climate crisis as a chain of causes and effects. Greenhouse gases trap heat in the atmosphere, deforestation destroys entire ecosystems, and pollution harms both people and wildlife. Conservation projects try to reverse some of this damage, but progress is slow.", "translation": "Especialistas descrevem a crise climática como uma cadeia de causas e efeitos. Gases de efeito estufa retêm calor na atmosfera, o desmatamento destrói ecossistemas inteiros, e a poluição prejudica tanto pessoas quanto a vida selvagem. Projetos de conservação tentam reverter parte desse dano, mas o progresso é lento.", "question": "What do greenhouse gases do, according to the text?", "options": ["Clean the air", "Trap heat in the atmosphere", "Destroy ecosystems directly"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000322', 'listening', 12, '{"audio_text": "Scientists warn that the climate crisis is accelerating. Deforestation has increased in the region this year. Air pollution is a serious problem in big cities.", "question": "What has increased in the region this year, according to the audio?", "options": ["Conservation", "Deforestation", "Biodiversity"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000322', 'dictation', 13, '{"audio_text": "The organization focuses on wildlife conservation.", "expected": "The organization focuses on wildlife conservation."}'),
('20000000-0000-0000-0000-000000000322', 'typing', 14, '{"prompt_pt": "Traduza: ''O desmatamento e a poluição estão destruindo o ecossistema local.''", "expected": "Deforestation and pollution are destroying the local ecosystem.", "ai_review": true}'),

