('20000000-0000-0000-0000-000000000323', 'word_order', 9, '{"words": ["We", "need", "to", "reduce", "our", "dependence", "on", "fossil", "fuels"], "correct_sentence": "We need to reduce our dependence on fossil fuels", "translation": "Precisamos reduzir nossa dependência de combustíveis fósseis"}'),
('20000000-0000-0000-0000-000000000323', 'word_order', 10, '{"words": ["The", "wildfire", "destroyed", "thousands", "of", "acres", "of", "forest"], "correct_sentence": "The wildfire destroyed thousands of acres of forest", "translation": "O incêndio florestal destruiu milhares de acres de floresta"}'),
('20000000-0000-0000-0000-000000000323', 'reading', 11, '{"passage": "Environmental threats often connect to one another. Burning fossil fuels contributes to droughts and wildfires, which destroy habitats and contaminate water supplies. As a result, more species become endangered, and some eventually go extinct.", "translation": "Ameaças ambientais costumam estar conectadas entre si. Queimar combustíveis fósseis contribui para secas e incêndios florestais, que destroem habitats e contaminam o abastecimento de água. Como resultado, mais espécies ficam ameaçadas de extinção, e algumas eventualmente se tornam extintas.", "question": "What does burning fossil fuels contribute to, according to the text?", "options": ["Conservation projects", "Droughts and wildfires", "Recycling programs"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000323', 'listening', 12, '{"audio_text": "The chemical spill contaminated the river. This species has been endangered for decades. The wildfire destroyed thousands of acres of forest.", "question": "What did the chemical spill contaminate, according to the audio?", "options": ["The air", "The river", "The soil"], "correct_index": 1}'),
('20000000-0000-0000-0000-000000000323', 'dictation', 13, '{"audio_text": "This species has been endangered for decades.", "expected": "This species has been endangered for decades."}'),
('20000000-0000-0000-0000-000000000323', 'typing', 14, '{"prompt_pt": "Traduza: ''A seca e os incêndios florestais ameaçam espécies que já estão em perigo.''", "expected": "The drought and the wildfires threaten species that are already endangered.", "ai_review": true}'),

