('20000000-0000-0000-0000-000000000324', 'word_order', 9, '{"words": ["The", "factory", "produces", "too", "much", "waste"], "correct_sentence": "The factory produces too much waste", "translation": "A fábrica produz muito resíduo"}'),
('20000000-0000-0000-0000-000000000324', 'word_order', 10, '{"words": ["The", "airline", "offers", "to", "offset", "your", "flight''s", "emissions"], "correct_sentence": "The airline offers to offset your flight''s emissions", "translation": "A companhia aérea oferece compensar as emissões do seu voo"}'),
('20000000-0000-0000-0000-000000000324', 'reading', 11, '{"passage": "As rising sea levels threaten coastal areas, cities are looking for ways to mitigate the damage. Individuals can help too: choosing to recycle, reducing waste, and buying eco-friendly products all make a difference. Some companies now let customers offset the environmental impact of their purchases.", "translation": "Com a elevação do nível do mar ameaçando áreas costeiras, cidades buscam formas de mitigar os danos. Indivíduos também podem ajudar: escolher reciclar, reduzir o desperdício e comprar produtos ecológicos fazem diferença. Algumas empresas agora permitem que os clientes compensem o impacto ambiental de suas compras.", "question": "What can individuals do to help, according to the text?", "options": ["Nothing, only governments can act", "Recycle, reduce waste, and buy eco-friendly products", "Only offset flights"], "correct_index": 1}'),
